if (!function_exists('terbilangRupiah')) {
    function terbilangRupiah($nilai) {
        // pakai helper global terbilang/formatRupiah jika sudah ada
        if (function_exists('terbilang')) {
            return ucwords(trim(terbilang((int)$nilai))) . ' Rupiah';
        }
        // fallback sederhana
        return number_format((float)$nilai, 0, ',', '.');
    }
}
